// Declaration: hoisted, callable before its line
function add(a, b) {
  return a + b;
}

// Expression: not callable before the assignment runs
const subtract = function (a, b) {
  return a - b;
};

// Arrow: concise; implicit return for a single expression
const multiply = (a, b) => a * b;
const makeUser = (name) => ({ name }); // wrap object literals in ()

function greet(name, greeting = 'Hello') {
  return `${greeting}, ${name}!`;
}

greet('Ada');            // 'Hello, Ada!'
greet();                 // 'Hello, undefined!'
greet('Ada', undefined); // 'Hello, Ada!'  default applies
greet('Ada', null);      // 'null, Ada!'   default does NOT apply to null

function sum(...nums) {  // rest parameter collects extras into a real array
  return nums.reduce((acc, n) => acc + n, 0);
}
sum(1, 2, 3);            // 6

function noReturn() { const x = 1; }
noReturn();        // undefined

function broken() {
  return            // automatic semicolon insertion ends the statement here
  {
    ok: true
  };
}
broken();          // undefined, not { ok: true }

function rename(user) {
  user.name = 'Bob';      // mutates the caller's object
  user = { name: 'Eve' }; // rebinds the local parameter only
}

const u = { name: 'Ada' };
rename(u);
u.name; // 'Bob'

// Impure: depends on and changes outside state
let total = 0;
function addToTotal(x) { total += x; }

// Pure
const addTax = (price, rate) => price * (1 + rate);
